options(stringsAsFactors=FALSE)
suppressPackageStartupMessages(library(glmmTMB));suppressPackageStartupMessages(library(DHARMa))
root<-normalizePath('09_MODERATION_DATASET_SEARCH/bikeshare_profile',winslash='/');out<-file.path(root,'outputs')
b<-readRDS(file.path(out,'full_bundle.rds'));d<-b$data
args<-commandArgs(trailingOnly=TRUE);label<-if(length(args))args[1] else 'primary'
m<-if(label=='primary')b$models$joint else readRDS(file.path(out,'sensitivity_models',paste0(label,'.rds')))
stopifnot(m$fit$convergence==0,isTRUE(m$sdr$pdHess))
m$call$data<-quote(d)
dest<-file.path(out,'diagnostics',label);dir.create(dest,recursive=TRUE,showWarnings=FALSE)
dh<-simulateResiduals(m,n=500,refit=FALSE,plot=FALSE,seed=20261017)
saveRDS(dh,file.path(dest,'DHARMa.rds'))
tests<-list(uniformity=testUniformity(dh,plot=FALSE),dispersion=testDispersion(dh,plot=FALSE),zero_inflation=testZeroInflation(dh,plot=FALSE),day_aggregated_uniformity=testUniformity(recalculateResiduals(dh,group=d$group),plot=FALSE))
tab<-do.call(rbind,lapply(names(tests),function(nm){a<-tests[[nm]];data.frame(test=nm,statistic=paste(signif(a$statistic,8),collapse=';'),p=a$p.value,method=a$method)}))
write.csv(tab,file.path(dest,'tests.csv'),row.names=FALSE);print(tab)
sim<-as.matrix(dh$simulatedResponse)
statsfun<-function(y)c(mean=mean(y),variance=var(y),zero_fraction=mean(y==0),positive_mean=mean(y[y>0]),max=max(y),all_zero_days=sum(rowsum(y,d$group,reorder=FALSE)==0))
ss<-apply(sim,2,statsfun);obs<-statsfun(d$y)
check<-data.frame(statistic=names(obs),observed=obs,simulation_median=apply(ss,1,median),lower=apply(ss,1,quantile,.025),upper=apply(ss,1,quantile,.975))
write.csv(check,file.path(dest,'predictive_checks.csv'),row.names=FALSE);print(check)
strata<-interaction(d$context,cut(d$hr,c(-1,5,9,15,19,23),labels=c('00-05','06-09','10-15','16-19','20-23')),drop=TRUE)
cal<-do.call(rbind,lapply(levels(strata),function(st){ii<-which(strata==st);zz<-sim[ii,,drop=FALSE];vals<-rbind(mean_y=colMeans(zz),zero_fraction=colMeans(zz==0),positive_mean=colSums(zz)/pmax(1,colSums(zz>0)));obs<-c(mean_y=mean(d$y[ii]),zero_fraction=mean(d$y[ii]==0),positive_mean=mean(d$y[ii][d$y[ii]>0]));data.frame(stratum=st,context=d$context[ii[1]],hour=mean(d$hr[ii]),n=length(ii),metric=names(obs),observed=obs,simulation_median=apply(vals,1,median),lower=apply(vals,1,quantile,.025),upper=apply(vals,1,quantile,.975))}))
write.csv(cal,file.path(dest,'calibration.csv'),row.names=FALSE)
r<-data.frame(date=d$dteday,context=d$context,hour=d$hr,residual=dh$scaledResiduals)
write.csv(r,file.path(dest,'residuals.csv'),row.names=FALSE)
dr<-aggregate(residual~date,r,mean);full_dates<-seq(as.Date(min(dr$date)),as.Date(max(dr$date)),by='day')
v<-dr$residual[match(as.character(full_dates),dr$date)]
acfdata<-do.call(rbind,lapply(1:28,function(l){a<-v[(l+1):length(v)];z<-v[1:(length(v)-l)];data.frame(lag=l,correlation=cor(a,z,use='complete.obs'),pairs=sum(complete.cases(a,z)))}))
write.csv(acfdata,file.path(dest,'calendar_residual_correlations.csv'),row.names=FALSE)
figdir<-file.path(root,'figures');dir.create(figdir,showWarnings=FALSE)
png(file.path(figdir,paste0('DHARMa_',label,'.png')),width=1600,height=800,res=140);plot(dh);dev.off()
